.version 7.8
.target sm_89
.address_size 64
// Structural rewrite: one CTA per (b, oc, od, oh) output row.
// The input row x[b, ic, id, ih, 0:64] is staged once into shared memory
// per (ic, kd, kh) combination and reused across all 70 output-width
// positions and all 7 kw taps within the CTA, removing the redundant
// global loads of the direct one-thread-per-output implementation.
.visible .entry conv_transpose3d_kernel(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 out_ptr,
    .param .u32 total_elements
)
{
    .reg .b32 %r<110>;
    .reg .b64 %rd<50>;
    .reg .f32 %f<20>;
    .reg .pred %p<40>;
    .shared .align 16 .b8 smem_x[256];
    ld.param.u64 %rd1, [x_ptr];
    ld.param.u64 %rd2, [w_ptr];
    ld.param.u64 %rd3, [out_ptr];
    ld.param.u32 %r1, [total_elements];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    mov.u32 %r2, %ctaid.x;   // block id -> (b,oc,od,oh)
    mov.u32 %r3, %tid.x;     // thread id -> maps to ow and ow+35, blockDim=64
    // decode block index
    rem.u32 %r11, %r2, 36;    // oh
    div.u32 %r12, %r2, 36;    // t1
    rem.u32 %r13, %r12, 18;   // od
    div.u32 %r14, %r12, 18;   // t2
    rem.u32 %r15, %r14, 16;   // oc
    div.u32 %r16, %r14, 16;   // b
    setp.lt.u32 %p1, %r3, 35;  // valid compute lane (handles two outputs per thread)
    add.u32 %r5, %r3, 35;      // ow2 = tid + 35 (register-blocked second output)
    mov.f32 %f1, 0f00000000;   // accumulator for ow1
    mov.f32 %f6, 0f00000000;   // accumulator for ow2
    mov.u32 %r20, 0;  // ic
LOOP_IC:
    setp.ge.u32 %p2, %r20, 32;
    @%p2 bra END_IC;
    mov.u32 %r21, 0;  // kd
LOOP_KD:
    setp.ge.u32 %p3, %r21, 3;
    @%p3 bra END_KD;
    sub.s32 %r22, %r13, %r21;   // id = od - kd
    setp.lt.s32 %p4, %r22, 0;
    setp.ge.s32 %p5, %r22, 16;
    or.pred %p6, %p4, %p5;
    @%p6 bra INC_KD;
    mov.u32 %r23, 0;  // kh
LOOP_KH:
    setp.ge.u32 %p7, %r23, 5;
    @%p7 bra END_KH;
    sub.s32 %r24, %r11, %r23;   // ih = oh - kh
    setp.lt.s32 %p8, %r24, 0;
    setp.ge.s32 %p9, %r24, 32;
    or.pred %p10, %p8, %p9;
    @%p10 bra INC_KH;
    // base offset (elements) for x[b,ic,id,ih,0]
    mul.lo.u32 %r30, %r16, 1048576;
    mul.lo.u32 %r31, %r20, 32768;
    add.u32 %r30, %r30, %r31;
    mul.lo.u32 %r31, %r22, 2048;
    add.u32 %r30, %r30, %r31;
    mul.lo.u32 %r31, %r24, 64;
    add.u32 %r30, %r30, %r31;
    bar.sync 0;
    setp.lt.u32 %p11, %r3, 16;
    @!%p11 bra SKIP_LOAD;
    mul.lo.u32 %r32, %r3, 4;
    add.u32 %r32, %r30, %r32;
    mul.wide.u32 %rd11, %r32, 4;
    add.u64 %rd12, %rd1, %rd11;
    ld.global.v4.f32 {%f2, %f3, %f4, %f5}, [%rd12];
    mul.lo.u32 %r33, %r3, 16;
    mov.u32 %r34, smem_x;
    add.u32 %r34, %r34, %r33;
    st.shared.v4.f32 [%r34], {%f2, %f3, %f4, %f5};
SKIP_LOAD:
    bar.sync 0;
    mov.u32 %r25, 0;  // kw
LOOP_KW:
    setp.ge.u32 %p12, %r25, 7;
    @%p12 bra END_KW;
    not.pred %p13, %p1;
    @%p13 bra INC_KW;
    // weight index (shared across both outputs, independent of ow)
    mul.lo.u32 %r40, %r20, 1680;
    mul.lo.u32 %r41, %r15, 105;
    add.u32 %r40, %r40, %r41;
    mul.lo.u32 %r41, %r21, 35;
    add.u32 %r40, %r40, %r41;
    mul.lo.u32 %r41, %r23, 7;
    add.u32 %r40, %r40, %r41;
    add.u32 %r40, %r40, %r25;
    mul.wide.u32 %rd13, %r40, 4;
    add.u64 %rd14, %rd2, %rd13;
    ld.global.f32 %f8, [%rd14];
    // first output (ow1 = tid)
    sub.s32 %r26, %r3, %r25;    // iw1 = ow1 - kw
    setp.lt.s32 %p14, %r26, 0;
    setp.ge.s32 %p15, %r26, 64;
    or.pred %p16, %p14, %p15;
    @%p16 bra SKIP1;
    mul.lo.u32 %r35, %r26, 4;
    mov.u32 %r36, smem_x;
    add.u32 %r36, %r36, %r35;
    ld.shared.f32 %f2, [%r36];
    fma.rn.f32 %f1, %f2, %f8, %f1;
SKIP1:
    // second output (ow2 = tid + 35)
    sub.s32 %r27, %r5, %r25;    // iw2 = ow2 - kw
    setp.lt.s32 %p17, %r27, 0;
    setp.ge.s32 %p18, %r27, 64;
    or.pred %p19, %p17, %p18;
    @%p19 bra INC_KW;
    mul.lo.u32 %r37, %r27, 4;
    mov.u32 %r38, smem_x;
    add.u32 %r38, %r38, %r37;
    ld.shared.f32 %f9, [%r38];
    fma.rn.f32 %f6, %f9, %f8, %f6;
INC_KW:
    add.u32 %r25, %r25, 1;
    bra LOOP_KW;
END_KW:
INC_KH:
    add.u32 %r23, %r23, 1;
    bra LOOP_KH;
END_KH:
INC_KD:
    add.u32 %r21, %r21, 1;
    bra LOOP_KD;
END_KD:
    add.u32 %r20, %r20, 1;
    bra LOOP_IC;
END_IC:
    @!%p1 bra DONE;
    mul.lo.u32 %r50, %r16, 725760;
    mul.lo.u32 %r51, %r15, 45360;
    add.u32 %r50, %r50, %r51;
    mul.lo.u32 %r51, %r13, 2520;
    add.u32 %r50, %r50, %r51;
    mul.lo.u32 %r51, %r11, 70;
    add.u32 %r50, %r50, %r51;
    add.u32 %r52, %r50, %r3;
    mul.wide.u32 %rd20, %r52, 4;
    add.u64 %rd21, %rd3, %rd20;
    st.global.f32 [%rd21], %f1;
    add.u32 %r53, %r50, %r5;
    mul.wide.u32 %rd22, %r53, 4;
    add.u64 %rd23, %rd3, %rd22;
    st.global.f32 [%rd23], %f6;
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv_transpose3d_kernel")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0),
                 output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels, kernel_size,
            stride=stride, padding=padding, output_padding=output_padding,
            groups=groups, bias=bias
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        weight = self.conv_transpose3d.weight.contiguous()

        B, C_in, D_in, H_in, W_in = x.shape
        out_channels = self.conv_transpose3d.out_channels
        kD, kH, kW = self.conv_transpose3d.kernel_size
        sD, sH, sW = self.conv_transpose3d.stride
        pD, pH, pW = self.conv_transpose3d.padding
        opD, opH, opW = self.conv_transpose3d.output_padding

