            (B, out_channels, D_out, H_out, W_out),
            dtype=x.dtype, device=x.device
        )

        total = output.numel()
        module = _get_ptx_module()

        block = 64
        num_blocks = B * out_channels * D_out * H_out
        grid = num_blocks
        module.launch(
            "conv_transpose3d_kernel",
            grid=(grid, 1, 1),
            block=(block, 1, 1),
            arguments=[x, weight, output, i32(total)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

